import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  ArrowLeft, 
  Download, 
  Share2, 
  BarChart3, 
  Award,
  XCircle
} from 'lucide-react';
import toast from 'react-hot-toast';

const FinalResults = () => {
  const { interviewId } = useParams();
  const navigate = useNavigate();
  const [reportData, setReportData] = useState(null);
  const [loading, setLoading] = useState(true);

  const loadFinalResults = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/get-final-results/${interviewId}`);
      if (response.ok) {
        const data = await response.json();
        setReportData(data);
      } else {
        throw new Error('Failed to load final results');
      }
    } catch (error) {
      console.error('Error loading final results:', error);
      toast.error('Failed to load final results');
    } finally {
      setLoading(false);
    }
  }, [interviewId]);

  useEffect(() => {
    if (interviewId) {
      loadFinalResults();
    }
  }, [loadFinalResults, interviewId]);



  const downloadReport = () => {
    try {
      console.log('📄 Attempting to download report for interview:', interviewId);
      const downloadUrl = `/api/download-final-report/${interviewId}`;
      console.log('📄 Download URL:', downloadUrl);
      
      // Create a temporary link element to trigger download
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.target = '_blank';
      link.download = `interview-report-${interviewId}.html`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      
      toast.success('Download started!');
    } catch (error) {
      console.error('❌ Download error:', error);
      toast.error('Download failed. Please try again.');
    }
  };

  const shareReport = () => {
    const url = window.location.href;
    if (navigator.share) {
      navigator.share({
        title: `Final Results - ${reportData?.interview?.candidate_name || 'Interview'}`,
        text: `View the final assessment results for ${reportData?.interview?.candidate_name || 'Interview'}`,
        url: url
      });
    } else {
      navigator.clipboard.writeText(url);
      toast.success('Report URL copied to clipboard');
    }
  };

  const getScoreColor = (score) => {
    if (score >= 8) return 'text-green-400';
    if (score >= 6) return 'text-yellow-400';
    return 'text-red-400';
  };

  const getScoreLabel = (score) => {
    if (score >= 8) return 'Excellent';
    if (score >= 6) return 'Good';
    if (score >= 4) return 'Fair';
    return 'Needs Improvement';
  };

  const getScoreClass = (score) => {
    if (score >= 8) return 'bg-green-500';
    if (score >= 6) return 'bg-yellow-500';
    if (score >= 4) return 'bg-orange-500';
    return 'bg-red-500';
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-900 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto"></div>
          <p className="text-gray-300 mt-4">Loading final results...</p>
        </div>
      </div>
    );
  }

  if (!reportData) {
    return (
      <div className="min-h-screen bg-gray-900 flex items-center justify-center">
        <div className="text-center">
          <XCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
          <h2 className="text-xl font-semibold text-white mb-2">Results Not Found</h2>
          <p className="text-gray-300 mb-4">The interview results could not be loaded.</p>
          <button
            onClick={() => navigate('/dashboard')}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg"
          >
            Go to Dashboard
          </button>
        </div>
      </div>
    );
  }

  const { interview, parameters, questions, answers } = reportData;

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      {/* Header */}
      <div className="bg-gray-800 border-b border-gray-700">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <button
                onClick={() => navigate('/dashboard')}
                className="flex items-center space-x-2 text-gray-300 hover:text-white transition-colors"
              >
                <ArrowLeft className="h-5 w-5" />
                <span>Back to Dashboard</span>
              </button>
            </div>
            <div className="flex items-center space-x-4">
              <button
                onClick={downloadReport}
                className="flex items-center space-x-2 bg-blue-600 hover:bg-blue-700 px-4 py-2 rounded-lg transition-colors"
              >
                <Download className="h-4 w-4" />
                <span>Download Report</span>
              </button>
              <button
                onClick={shareReport}
                className="flex items-center space-x-2 bg-gray-700 hover:bg-gray-600 px-4 py-2 rounded-lg transition-colors"
              >
                <Share2 className="h-4 w-4" />
                <span>Share</span>
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Interview Overview */}
        <div className="bg-gray-800 rounded-lg p-6 mb-8">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="text-center">
              <div className="text-3xl font-bold text-blue-400">{interview.overall_score?.toFixed(1) || 'N/A'}/10</div>
              <div className="text-sm text-gray-400">Overall Score</div>
              <div className={`text-xs mt-1 px-2 py-1 rounded-full ${getScoreClass(interview.overall_score || 0)}`}>
                {getScoreLabel(interview.overall_score || 0)} Performance
              </div>
            </div>
            <div className="text-center">
              <div className="text-3xl font-bold text-green-400">{parameters?.length || 0}</div>
              <div className="text-sm text-gray-400">Parameters Assessed</div>
            </div>
            <div className="text-center">
              <div className="text-3xl font-bold text-yellow-400">{interview.total_questions || 0}</div>
              <div className="text-sm text-gray-400">Total Questions</div>
            </div>
            <div className="text-center">
              <div className="text-3xl font-bold text-purple-400">{interview.session_duration || 0} min</div>
              <div className="text-sm text-gray-400">Duration</div>
            </div>
          </div>
        </div>

        {/* Parameter Scores */}
        {parameters && parameters.length > 0 && (
          <div className="bg-gray-800 rounded-lg p-6 mb-8">
            <h2 className="text-xl font-semibold mb-6 flex items-center">
              <BarChart3 className="h-5 w-5 mr-2" />
              Parameter Performance
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {parameters.map((param, index) => (
                <div key={index} className="bg-gray-700 rounded-lg p-4">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-semibold text-lg">{param.name}</h3>
                    <div className={`text-2xl font-bold ${getScoreColor(param.score)}`}>
                      {param.score}/10
                    </div>
                  </div>
                  <div className="mb-3">
                    <div className="flex justify-between text-sm text-gray-400 mb-1">
                      <span>Weight: {param.weight}%</span>
                      <span>{param.questions_asked} questions</span>
                    </div>
                    <div className="w-full bg-gray-600 rounded-full h-2">
                      <div 
                        className={`h-2 rounded-full ${getScoreClass(param.score)}`}
                        style={{ width: `${param.score * 10}%` }}
                      ></div>
                    </div>
                  </div>
                  <p className="text-sm text-gray-300">{param.assessment}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Detailed Questions and Answers */}
        {questions && questions.length > 0 && (
          <div className="bg-gray-800 rounded-lg p-6">
            <h2 className="text-xl font-semibold mb-6 flex items-center">
              <Award className="h-5 w-5 mr-2" />
              Detailed Assessment
            </h2>
            <div className="space-y-6">
              {questions.map((question, index) => {
                const answer = answers?.find(a => a.question_order === question.question_order);
                return (
                  <div key={index} className="bg-gray-700 rounded-lg p-6">
                    <div className="flex items-center justify-between mb-4">
                      <h3 className="text-lg font-semibold">Question {question.question_order + 1}</h3>
                      {answer && (
                        <div className={`text-xl font-bold ${getScoreColor(answer.score)}`}>
                          {answer.score}/10
                        </div>
                      )}
                    </div>
                    
                    <div className="mb-4">
                      <h4 className="font-medium text-gray-300 mb-2">Question:</h4>
                      <p className="text-gray-200">{question.question_text}</p>
                    </div>

                    {answer && (
                      <>
                        <div className="mb-4">
                          <h4 className="font-medium text-gray-300 mb-2">Your Answer:</h4>
                          <p className="text-gray-200">{answer.transcript}</p>
                        </div>

                        {answer.audio_url && (
                          <div className="mb-4">
                            <h4 className="font-medium text-gray-300 mb-2">Audio Recording:</h4>
                            <audio 
                              controls 
                              className="w-full"
                              src={answer.audio_url}
                            >
                              Your browser does not support the audio element.
                            </audio>
                          </div>
                        )}

                        {answer.feedback && (
                          <div className="mb-4">
                            <h4 className="font-medium text-gray-300 mb-2">AI Feedback:</h4>
                            <p className="text-gray-200">{answer.feedback}</p>
                          </div>
                        )}
                      </>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default FinalResults;
