import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster, toast } from 'react-hot-toast';
import InterviewSetup from './components/InterviewSetup';
import ConversationalInterview from './components/ConversationalInterview';
import InterviewDashboard from './components/InterviewDashboard';
import FinalResults from './components/FinalResults';
import WelcomePage from './components/WelcomePage';
import CustomParameterManager from './components/CustomParameterManager';
import HRInterviewCreator from './components/HRInterviewCreator';
import CandidateInterview from './components/CandidateInterview';
import CandidateCompletion from './components/CandidateCompletion';

// Add toast.info method to prevent errors
if (!toast.info) {
  toast.info = (message, options) => {
    return toast(message, {
      icon: 'ℹ️',
      style: {
        background: '#3b82f6',
        color: '#fff',
      },
      ...options
    });
  };
}

function App() {
  return (
    <Router>
      <div className="App">
        <Toaster 
          position="top-right"
          toastOptions={{
            duration: 4000,
            style: {
              background: '#1f2937',
              color: '#fff',
              border: '1px solid #374151',
            },
            success: {
              iconTheme: {
                primary: '#10b981',
                secondary: '#fff',
              },
            },
            error: {
              iconTheme: {
                primary: '#ef4444',
                secondary: '#fff',
              },
            },
          }}
        />

        <Routes>
          <Route path="/" element={<WelcomePage />} />
          <Route path="/setup" element={<InterviewSetup />} />

          {/* HR/Admin Routes */}
          <Route path="/hr/create-interview" element={<HRInterviewCreator />} />
          <Route path="/dashboard" element={<InterviewDashboard />} />
          <Route path="/parameters" element={<CustomParameterManager />} />

          {/* Candidate Routes */}
          <Route path="/interview/:interviewId" element={<CandidateInterview />} />
          <Route path="/conversational-interview" element={<ConversationalInterview />} />
          <Route path="/candidate-completion" element={<CandidateCompletion />} />
          
          {/* HR-Only Routes (Protected) */}
          <Route path="/final-results/:interviewId" element={<FinalResults />} />

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
