import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Users, Play, Pause, Download, Eye, Search,
  SortAsc, SortDesc, RefreshCw,
  Award, Clock, User, 
  BarChart3, X, Plus, Headphones
} from 'lucide-react';
import toast from 'react-hot-toast';

const InterviewDashboard = () => {
  const navigate = useNavigate();
  const [interviews, setInterviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedInterview, setSelectedInterview] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState('created_at');
  const [sortOrder, setSortOrder] = useState('desc');
  const [filterStatus, setFilterStatus] = useState('all');
  const [playingAudio, setPlayingAudio] = useState(null);

  useEffect(() => {
    loadInterviews();
  }, []);

  const loadInterviews = async () => {
    try {
      setLoading(true);
      console.log('Loading interviews...');
      const response = await fetch('/api/get-all-interviews');
      console.log('Response status:', response.status);
      if (response.ok) {
        const data = await response.json();
        console.log('Interviews data:', data);
        setInterviews(data.interviews || []);
      } else {
        throw new Error('Failed to load interviews');
      }
    } catch (error) {
      console.error('Error loading interviews:', error);
      toast.error('Failed to load interviews');
    } finally {
      setLoading(false);
    }
  };

  const getInterviewDetails = async (interviewId) => {
    try {
      console.log('🔍 Fetching interview details for:', interviewId);
      
      // Try get-final-results first
      let response = await fetch(`/api/get-final-results/${interviewId}`);
      let data;
      
      if (response.ok) {
        data = await response.json();
        console.log('📊 Received final results data:', data);
      } else {
        // Fallback to regular get-interview endpoint
        console.log('⚠️ Final results failed, trying regular interview endpoint');
        response = await fetch(`/api/get-interview/${interviewId}`);
        if (response.ok) {
          data = await response.json();
          console.log('📊 Received regular interview data:', data);
        } else {
          throw new Error('Failed to load interview details from both endpoints');
        }
      }
      
      console.log('📋 Interview object:', data.interview);
      console.log('🎯 Parameters:', data.parameters);
      console.log('🔍 Full data structure:', JSON.stringify(data, null, 2));
      
      // Ensure we have the correct data structure with comprehensive mapping
      const interviewData = {
        ...data.interview,
        // Ensure we have all required fields with fallbacks
        candidate_name: data.interview?.candidate_name || data.candidate_name || 'N/A',
        candidate_email: data.interview?.candidate_email || data.candidate_email || 'Not provided',
        position: data.interview?.position || data.position || 'N/A',
        duration_minutes: data.interview?.duration_minutes || data.interview?.duration || data.duration_minutes || data.duration || 30,
        status: data.interview?.status || data.interview?.assessment_status || data.status || 'N/A',
        created_at: data.interview?.created_at || data.created_at || null,
        total_score: data.interview?.total_score || data.interview?.overall_score || data.total_score || data.overall_score || null,
        id: data.interview?.id || data.id || interviewId
      };
      
      console.log('🔧 Processed interview data:', interviewData);
      console.log('🔍 Raw interview data from API:', data.interview);
      console.log('🔍 Available fields:', Object.keys(data.interview || {}));
      console.log('🎯 Parameters data:', data.parameters);
      
      // Set both interview data and parameters
      const finalData = {
        ...interviewData,
        parameters: data.parameters || []
      };
      
      // If no parameters but we have answers, create basic parameter structure
      if (!data.parameters || data.parameters.length === 0) {
        console.log('⚠️ No parameters found, checking for answers...');
        if (data.answers && data.answers.length > 0) {
          console.log(`📝 Found ${data.answers.length} answers, creating basic parameter structure`);
          finalData.parameters = [{
            name: 'Interview Questions',
            questions: data.answers.map((answer, index) => ({
              question_text: answer.questions?.question_text || `Question ${index + 1}`,
              audio_url: answer.audio_url,
              score: answer.score,
              feedback: answer.feedback,
              duration_sec: 60 // Default duration
            })),
            score: data.answers.reduce((sum, answer) => sum + (answer.score || 0), 0) / data.answers.length,
            weight: 100
          }];
        }
      }
      
      setSelectedInterview(finalData);
    } catch (error) {
      console.error('Error loading interview details:', error);
      toast.error('Failed to load interview details');
    }
  };



  const playAudio = (audioUrl) => {
    console.log('🎵 Attempting to play audio:', audioUrl);
    
    // Test if audio URL is accessible
    fetch(audioUrl, { method: 'HEAD' })
      .then(response => {
        console.log('🔍 Audio URL status:', response.status, response.ok);
        if (!response.ok) {
          console.error('❌ Audio file not accessible:', audioUrl);
          toast.error('Audio file not accessible');
          return;
        }
      })
      .catch(error => {
        console.error('❌ Error checking audio URL:', error);
        toast.error('Error accessing audio file');
        return;
      });
    
    if (playingAudio === audioUrl) {
      console.log('⏸️ Pausing audio');
      setPlayingAudio(null);
    } else {
      console.log('▶️ Playing audio');
      setPlayingAudio(audioUrl);
    }
  };



  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    try {
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return 'Invalid Date';
      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch (error) {
      console.error('Error formatting date:', error, dateString);
      return 'Invalid Date';
    }
  };

  const formatDuration = (minutes) => {
    return `${minutes} min`;
  };







  const getStatusColor = (status) => {
    switch (status) {
      case 'completed': return 'text-green-600 bg-green-50';
      case 'active': return 'text-blue-600 bg-blue-50';
      case 'in_progress': return 'text-blue-600 bg-blue-50';
      case 'pending': return 'text-yellow-600 bg-yellow-50';
      case 'expired': return 'text-red-600 bg-red-50';
      default: return 'text-gray-600 bg-gray-50';
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'completed': return <Award className="w-4 h-4" />;
      case 'active': return <Clock className="w-4 h-4" />;
      case 'in_progress': return <Clock className="w-4 h-4" />;
      case 'pending': return <Clock className="w-4 h-4" />;
      case 'expired': return <X className="w-4 h-4" />;
      default: return <Clock className="w-4 h-4" />;
    }
  };

  const filteredInterviews = interviews
    .filter(interview => {
      const matchesSearch = interview.candidate_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                           interview.position.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus = filterStatus === 'all' || interview.status === filterStatus;
      return matchesSearch && matchesStatus;
    })
    .sort((a, b) => {
      let comparison = 0;
      switch (sortBy) {
        case 'candidate_name':
          comparison = a.candidate_name.localeCompare(b.candidate_name);
          break;
        case 'position':
          comparison = a.position.localeCompare(b.position);
          break;
        case 'total_score':
          comparison = (a.total_score || 0) - (b.total_score || 0);
          break;
        case 'created_at':
          comparison = new Date(a.created_at) - new Date(b.created_at);
          break;
        default:
          comparison = 0;
      }
      return sortOrder === 'asc' ? comparison : -comparison;
    });

  const stats = {
    total: interviews.length,
    completed: interviews.filter(i => i.status === 'completed').length,
    active: interviews.filter(i => i.status === 'active' || i.status === 'in_progress').length,
    pending: interviews.filter(i => i.status === 'pending').length,
    avgScore: interviews.filter(i => i.status === 'completed' && i.total_score).length > 0 
      ? (interviews.filter(i => i.status === 'completed' && i.total_score)
          .reduce((sum, i) => sum + i.total_score, 0) / 
         interviews.filter(i => i.status === 'completed' && i.total_score).length).toFixed(1)
      : 'N/A'
  };

  return (
    <div className="min-h-screen bg-slate-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="bg-white rounded-2xl p-6 shadow-lg border border-gray-100 mb-6">
                     <div className="flex items-center justify-between mb-6">
             <div>
               <h1 className="text-3xl font-bold text-gray-900">Interview Dashboard</h1>
               <p className="text-gray-600 mt-2">Manage and analyze interview sessions</p>
             </div>
             <div className="flex gap-3">
               <button
                 onClick={() => navigate('/hr/create-interview')}
                 className="bg-gradient-to-r from-blue-600 to-purple-600 text-white px-6 py-3 rounded-xl font-semibold hover:shadow-lg transition-all duration-300 flex items-center gap-2"
               >
                 <Plus className="w-5 h-5" />
                 Create Interview
               </button>
               <button
                 onClick={() => navigate('/setup')}
                 className="bg-gradient-to-r from-green-600 to-green-700 text-white px-6 py-3 rounded-xl font-semibold hover:shadow-lg transition-all duration-300 flex items-center gap-2"
               >
                 <Users className="w-5 h-5" />
                 Practice Mode
               </button>
             </div>
           </div>

          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="bg-gradient-to-r from-blue-50 to-blue-100 rounded-xl p-4 border border-blue-200">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-blue-500 rounded-lg flex items-center justify-center">
                  <Users className="w-5 h-5 text-white" />
                </div>
                <div>
                  <div className="text-2xl font-bold text-blue-900">{stats.total}</div>
                  <div className="text-blue-600 text-sm">Total Interviews</div>
                </div>
              </div>
            </div>

            <div className="bg-gradient-to-r from-green-50 to-green-100 rounded-xl p-4 border border-green-200">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-green-500 rounded-lg flex items-center justify-center">
                  <Award className="w-5 h-5 text-white" />
                </div>
                <div>
                  <div className="text-2xl font-bold text-green-900">{stats.completed}</div>
                  <div className="text-green-600 text-sm">Completed</div>
                </div>
              </div>
            </div>

            <div className="bg-gradient-to-r from-purple-50 to-purple-100 rounded-xl p-4 border border-purple-200">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-purple-500 rounded-lg flex items-center justify-center">
                  <Clock className="w-5 h-5 text-white" />
                </div>
                <div>
                  <div className="text-2xl font-bold text-purple-900">{stats.active}</div>
                  <div className="text-purple-600 text-sm">Active</div>
                </div>
              </div>
            </div>

            <div className="bg-gradient-to-r from-orange-50 to-orange-100 rounded-xl p-4 border border-orange-200">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-orange-500 rounded-lg flex items-center justify-center">
                  <BarChart3 className="w-5 h-5 text-white" />
                </div>
                <div>
                  <div className="text-2xl font-bold text-orange-900">{stats.avgScore}</div>
                  <div className="text-orange-600 text-sm">Avg Score</div>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Filters and Search */}
        <div className="bg-white rounded-2xl p-6 shadow-lg border border-gray-100 mb-6">
          <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
            <div className="flex items-center gap-4 flex-1">
              <div className="relative flex-1 max-w-md">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input
                  type="text"
                  placeholder="Search by candidate name or position..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
              </div>

              <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="all">All Status</option>
                <option value="pending">Pending</option>
                <option value="active">Active</option>
                <option value="in_progress">In Progress</option>
                <option value="completed">Completed</option>
                <option value="expired">Expired</option>
              </select>
            </div>

            <div className="flex items-center gap-2">
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                className="px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="created_at">Date</option>
                <option value="candidate_name">Candidate</option>
                <option value="position">Position</option>
              </select>

              <button
                onClick={() => setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')}
                className="p-2 border border-gray-200 rounded-lg hover:bg-gray-50"
              >
                {sortOrder === 'asc' ? <SortAsc className="w-4 h-4" /> : <SortDesc className="w-4 h-4" />}
              </button>

              <button
                onClick={loadInterviews}
                className="p-2 border border-gray-200 rounded-lg hover:bg-gray-50"
              >
                <RefreshCw className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>

        {/* Interviews List */}
        <div className="bg-white rounded-2xl shadow-lg border border-gray-100">
          {loading ? (
            <div className="p-8 text-center">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto"></div>
              <p className="text-gray-600 mt-2">Loading interviews...</p>
            </div>
          ) : filteredInterviews.length === 0 ? (
            <div className="p-8 text-center">
              <Users className="w-12 h-12 text-gray-400 mx-auto mb-4" />
              <p className="text-gray-600">No interviews found</p>
              <p className="text-gray-500 text-sm mt-2">Start your first interview to see results here</p>
              <button
                onClick={() => navigate('/setup')}
                className="mt-4 bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg transition-colors"
              >
                Start New Interview
              </button>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-6 py-4 text-left text-sm font-semibold text-gray-900">Candidate</th>
                    <th className="px-6 py-4 text-left text-sm font-semibold text-gray-900">Position</th>
                    <th className="px-6 py-4 text-left text-sm font-semibold text-gray-900">Status</th>
                    <th className="px-6 py-4 text-left text-sm font-semibold text-gray-900">Duration</th>
                    <th className="px-6 py-4 text-left text-sm font-semibold text-gray-900">Date</th>
                    <th className="px-6 py-4 text-left text-sm font-semibold text-gray-900">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200">
                  {filteredInterviews.map((interview) => (
                    <tr key={interview.id} className="hover:bg-gray-50">
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center">
                            <User className="w-4 h-4 text-blue-600" />
                          </div>
                          <div>
                            <div className="font-medium text-gray-900">{interview.candidate_name}</div>
                            <div className="text-sm text-gray-500">ID: {interview.id.slice(0, 8)}...</div>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-purple-100 text-purple-800">
                          {interview.position}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getStatusColor(interview.status)}`}>
                          {getStatusIcon(interview.status)}
                          <span className="ml-1 capitalize">{interview.status.replace('_', ' ')}</span>
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-900">
                        {formatDuration(interview.duration_minutes)}
                      </td>
                      <td className="px-6 py-4 text-sm text-gray-900">
                        {formatDate(interview.created_at)}
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2">
                          <button
                            onClick={() => getInterviewDetails(interview.id)}
                            className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                            title="View Details"
                          >
                            <Eye className="w-4 h-4" />
                          </button>
                          
                          {interview.status === 'completed' && (
                            <button
                              onClick={() => window.open(`/final-results/${interview.id}`, '_blank')}
                              className="p-2 text-purple-600 hover:bg-purple-50 rounded-lg transition-colors"
                              title="View Final Results"
                            >
                              <BarChart3 className="w-4 h-4" />
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Interview Details Modal */}
        {selectedInterview && selectedInterview.id && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-2xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
              <div className="p-6 border-b border-gray-200">
                <div className="flex items-center justify-between">
                  <div>
                    <h2 className="text-2xl font-bold text-gray-900">Interview Details</h2>
                    <p className="text-gray-600 mt-1">
                      {selectedInterview?.interview?.candidate_name || selectedInterview?.candidate_name || 'N/A'} - {selectedInterview?.interview?.position || selectedInterview?.position || 'N/A'}
                    </p>
                  </div>
                  <div className="flex items-center gap-3">
                    {((selectedInterview?.interview?.status === 'completed' || selectedInterview?.interview?.assessment_status === 'completed') || 
                      (selectedInterview?.status === 'completed' || selectedInterview?.assessment_status === 'completed')) && (
                      <button
                        onClick={() => {
                          window.open(`/final-results/${selectedInterview?.interview?.id || selectedInterview?.id}`, '_blank');
                          setSelectedInterview(null);
                        }}
                        className="flex items-center gap-2 bg-purple-600 hover:bg-purple-700 text-white px-4 py-2 rounded-lg transition-colors"
                      >
                        <BarChart3 className="w-4 h-4" />
                        View Full Results
                      </button>
                    )}
                    <button
                      onClick={() => setSelectedInterview(null)}
                      className="text-gray-400 hover:text-gray-600"
                    >
                      <X className="w-6 h-6" />
                    </button>
                  </div>
                </div>
              </div>

              <div className="p-6">
                {/* Interview Summary */}
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
                  <div className="bg-blue-50 rounded-lg p-4">
                    <div className="text-sm text-blue-600 font-medium">Weighted Score</div>
                    <div className="text-2xl font-bold text-blue-900">
                      {(() => {
                        const score = selectedInterview?.interview?.overall_score || selectedInterview?.overall_score || selectedInterview?.total_score;
                        console.log('🎯 Rendering overall score:', score);
                        return score ? score.toFixed(1) : 'N/A';
                      })()}/10
                    </div>
                  </div>
                  <div className="bg-green-50 rounded-lg p-4">
                    <div className="text-sm text-green-600 font-medium">Parameters Assessed</div>
                    <div className="text-2xl font-bold text-green-900">
                      {(() => {
                        const count = selectedInterview?.parameters?.length || 0;
                        console.log('🎯 Rendering parameters count:', count);
                        return count;
                      })()}
                    </div>
                  </div>
                  <div className="bg-purple-50 rounded-lg p-4">
                    <div className="text-sm text-purple-600 font-medium">Total Questions</div>
                    <div className="text-2xl font-bold text-purple-900">
                      {(() => {
                        const total = selectedInterview?.parameters?.reduce((total, param) => total + (param.questions?.length || 0), 0) || 0;
                        console.log('📝 Total questions:', total);
                        return total;
                      })()}
                    </div>
                  </div>
                  <div className="bg-orange-50 rounded-lg p-4">
                    <div className="text-sm text-orange-600 font-medium">Session Duration</div>
                    <div className="text-2xl font-bold text-orange-900">
                      {(() => {
                        const duration = selectedInterview?.interview?.session_duration || selectedInterview?.duration_minutes || selectedInterview?.duration;
                        console.log('⏱️ Session duration:', duration);
                        return duration ? `${duration} min` : 'N/A';
                      })()}
                    </div>
                  </div>
                </div>

                {/* Parameter-Based Results */}
                <div className="mb-6">
                  <h3 className="text-lg font-semibold text-gray-900 mb-4">Parameter-Based Scoring</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {selectedInterview?.parameters?.map((param, index) => (
                      <div key={index} className="border border-gray-200 rounded-lg p-4">
                        <div className="flex items-center justify-between mb-3">
                          <div className="flex items-center gap-2">
                            <span className="w-8 h-8 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center text-sm font-medium">
                              {index + 1}
                            </span>
                            <div>
                              <h4 className="font-semibold text-gray-900 capitalize">
                                {param.name.replace(/_/g, ' ')}
                              </h4>
                              <p className="text-sm text-gray-500">
                                Weight: {(() => {
                                  const weight = param.weight;
                                  console.log('🎯 Parameter weight:', param.name, weight);
                                  return weight ? `${weight}%` : '20%';
                                })()}
                              </p>
                            </div>
                          </div>
                          <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                            param.score >= 8 ? 'text-green-600 bg-green-50' : 
                            param.score >= 6 ? 'text-yellow-600 bg-yellow-50' : 'text-red-600 bg-red-50'
                          }`}>
                            {param.score}/10
                          </span>
                        </div>
                        
                        <div className="mb-3">
                          <div className="flex justify-between text-sm text-gray-600 mb-1">
                            <span>Score</span>
                            <span>{param.score}/10</span>
                          </div>
                          <div className="w-full bg-gray-200 rounded-full h-2">
                            <div 
                              className={`h-2 rounded-full ${
                                param.score >= 8 ? 'bg-green-500' : 
                                param.score >= 6 ? 'bg-yellow-500' : 'bg-red-500'
                              }`}
                              style={{ width: `${(param.score / 10) * 100}%` }}
                            />
                          </div>
                        </div>
                        
                        <div className="bg-gray-50 rounded-lg p-3">
                          <p className="text-sm text-gray-700">{param.reason}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Audio Recordings by Parameter */}
                <div className="mb-6">
                  <h3 className="text-lg font-semibold text-gray-900 mb-4">Audio Recordings by Parameter</h3>
                  <div className="space-y-4">
                    {selectedInterview?.parameters?.map((param, paramIndex) => (
                      <div key={paramIndex} className="border border-gray-200 rounded-lg p-4">
                        <div className="flex items-center gap-2 mb-3">
                          <span className="w-6 h-6 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center text-sm font-medium">
                            {paramIndex + 1}
                          </span>
                          <h4 className="font-semibold text-gray-900 capitalize">
                            {param.name.replace(/_/g, ' ')} - {param.questions?.length || 0} questions
                          </h4>
                        </div>
                        
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                          {param.questions?.map((question, qIndex) => (
                            <div key={qIndex} className="bg-gray-50 rounded-lg p-3">
                              <div className="flex items-center justify-between mb-2">
                                <span className="text-sm font-medium text-gray-700">Q{qIndex + 1}</span>
                                <span className="text-xs text-gray-500">
                                  {Math.floor(question.duration_sec / 60)}:{(question.duration_sec % 60).toString().padStart(2, '0')}
                                </span>
                              </div>
                              
                              {/* Show audio player for ALL questions with audio URLs */}
                              {question.audio_url ? (
                                <div className="flex items-center gap-2">
                                  <button
                                    onClick={() => playAudio(question.audio_url)}
                                    className="flex items-center gap-1 px-2 py-1 bg-blue-600 text-white rounded text-xs hover:bg-blue-700 transition-colors"
                                  >
                                    {playingAudio === question.audio_url ? (
                                      <Pause className="w-3 h-3" />
                                    ) : (
                                      <Play className="w-3 h-3" />
                                    )}
                                    {playingAudio === question.audio_url ? 'Pause' : 'Play'}
                                  </button>
                                  
                                  {playingAudio === question.audio_url && (
                                    <audio
                                      src={question.audio_url}
                                      controls
                                      className="flex-1 h-8"
                                      preload="metadata"
                                      onEnded={() => setPlayingAudio(null)}
                                                                              onError={(e) => {
                                          console.error('❌ Audio error:', e);
                                          console.error('❌ Audio URL:', question.audio_url);
                                          console.error('❌ Audio target:', e.target);
                                          console.error('❌ Audio error details:', e.target.error);
                                          
                                          // Show user-friendly error message
                                          toast.error('Audio playback not supported in this browser. Try a different browser or device.');
                                        }}
                                      onLoadStart={() => console.log('🔄 Audio loading started:', question.audio_url)}
                                      onCanPlay={() => console.log('✅ Audio can play:', question.audio_url)}
                                    />
                                  )}
                                </div>
                              ) : (
                                <div className="text-xs text-gray-500">No audio available</div>
                              )}
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Complete Session Video */}
                {selectedInterview?.interview?.session_video_url || selectedInterview?.session_video_url ? (
                  <div className="mb-6">
                    <h3 className="text-lg font-semibold text-gray-900 mb-4">Complete Session Video</h3>
                    <div className="border border-gray-200 rounded-lg p-4">
                      <div className="flex items-center justify-between mb-3">
                        <div className="flex items-center gap-2">
                          <span className="w-8 h-8 bg-red-100 text-red-600 rounded-full flex items-center justify-center text-sm font-medium">
                            🎥
                          </span>
                          <div>
                            <h4 className="font-semibold text-gray-900">Full Interview Session</h4>
                            <p className="text-sm text-gray-500">
                              Complete video recording from start to finish
                            </p>
                          </div>
                        </div>
                        <div className="text-right">
                          <div className="text-sm text-gray-600">
                            Size: {(() => {
                              const size = selectedInterview?.interview?.session_video_size || selectedInterview?.session_video_size;
                              return size ? `${(size / 1024 / 1024).toFixed(1)} MB` : 'N/A';
                            })()}
                          </div>
                          <div className="text-xs text-gray-500">
                            Format: WebM
                          </div>
                        </div>
                      </div>
                      
                      <div className="flex items-center gap-3">
                        <button
                          onClick={() => {
                            const videoUrl = selectedInterview?.interview?.session_video_url || selectedInterview?.session_video_url;
                            if (videoUrl) {
                              window.open(videoUrl, '_blank');
                            }
                          }}
                          className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
                        >
                          <Play className="w-4 h-4" />
                          Play Full Video
                        </button>
                        
                        <button
                          onClick={() => {
                            const videoUrl = selectedInterview?.interview?.session_video_url || selectedInterview?.session_video_url;
                            if (videoUrl) {
                              const link = document.createElement('a');
                              link.href = videoUrl;
                              link.download = `interview_session_${selectedInterview?.interview?.id || selectedInterview?.id}.webm`;
                              document.body.appendChild(link);
                              link.click();
                              document.body.removeChild(link);
                            }
                          }}
                          className="flex items-center gap-2 px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors"
                        >
                          <Download className="w-4 h-4" />
                          Download Video
                        </button>
                      </div>
                      
                      <div className="mt-3 text-xs text-gray-500">
                        <p>📹 This video contains the complete interview session including:</p>
                        <ul className="list-disc list-inside mt-1 space-y-1">
                          <li>Candidate's facial expressions and body language</li>
                          <li>Complete audio from all questions</li>
                          <li>Full session duration: {selectedInterview?.interview?.session_duration || selectedInterview?.duration_minutes || 'N/A'} minutes</li>
                          <li>Professional assessment context</li>
                        </ul>
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="mb-6">
                    <h3 className="text-lg font-semibold text-gray-900 mb-4">Complete Session Video</h3>
                    <div className="border border-gray-200 rounded-lg p-4">
                      <div className="text-center text-gray-500">
                        <div className="w-12 h-12 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-2">
                          <span className="text-gray-400">🎥</span>
                        </div>
                        <p className="text-sm">No session video available</p>
                        <p className="text-xs text-gray-400 mt-1">Video recording feature may not be enabled for this interview</p>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}


        
      </div>
    </div>
  );
};

export default InterviewDashboard;

