import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-hot-toast';
import {
  UserPlus,
  Settings,
  Copy,
  Send,
  FileText,
  Plus,
  Trash2,
  Save,
  Target,
  Brain,
  Loader2
} from 'lucide-react';

const HRInterviewCreator = () => {
  const navigate = useNavigate();
  
  // Form state
  const [formData, setFormData] = useState({
    candidateName: '',
    candidateEmail: '',
    position: '',
    duration: 30,
    technicalWeight: 60,
    softSkillsWeight: 40,
    customInstructions: '',
    interviewType: 'technical'
  });

  const [isCreating, setIsCreating] = useState(false);
  const [createdInterview, setCreatedInterview] = useState(null);
  
  // Parameter management state
  const [customParameters, setCustomParameters] = useState({});
  const [isLoadingParameters, setIsLoadingParameters] = useState(true);
  const [isSavingParameters, setIsSavingParameters] = useState(false);
  const [parametersSaved, setParametersSaved] = useState(false);
  const [showParametersTab, setShowParametersTab] = useState(false);

  // Available positions
  const positions = [
    'Software Engineer',
    'Data Scientist',
    'Product Manager',
    'UX Designer',
    'DevOps Engineer',
    'Frontend Developer',
    'Backend Developer',
    'Full Stack Developer',
    'QA Engineer',
    'System Administrator',
    'Business Analyst',
    'Project Manager'
  ];

  // Interview types
  const interviewTypes = [
    { value: 'technical', label: 'Technical Interview', icon: '💻' },
    { value: 'behavioral', label: 'Behavioral Interview', icon: '🤝' },
    { value: 'mixed', label: 'Mixed (Technical + Behavioral)', icon: '🎯' }
  ];

  // Example parameters for different roles
  const getExampleParameters = (role) => {
    const examples = {
      'Software Engineer': [
        { name: 'Technical Skills', description: 'Programming languages, frameworks, and technical problem-solving abilities', weight: 40 },
        { name: 'Problem Solving', description: 'Analytical thinking and approach to complex technical challenges', weight: 30 },
        { name: 'Communication', description: 'Ability to explain technical concepts and collaborate with teams', weight: 20 },
        { name: 'Learning Ability', description: 'Adaptability and willingness to learn new technologies', weight: 10 }
      ],
      'Data Scientist': [
        { name: 'Statistical Knowledge', description: 'Understanding of statistical methods and data analysis techniques', weight: 35 },
        { name: 'Machine Learning', description: 'ML algorithms, model development, and evaluation skills', weight: 35 },
        { name: 'Data Visualization', description: 'Ability to present insights through charts and dashboards', weight: 20 },
        { name: 'Business Acumen', description: 'Understanding of business context and stakeholder communication', weight: 10 }
      ],
      'Product Manager': [
        { name: 'Product Strategy', description: 'Vision, roadmap planning, and strategic thinking', weight: 35 },
        { name: 'User Research', description: 'Understanding user needs and market research skills', weight: 25 },
        { name: 'Cross-functional Leadership', description: 'Ability to lead engineering, design, and business teams', weight: 25 },
        { name: 'Data-driven Decision Making', description: 'Using metrics and analytics to inform product decisions', weight: 15 }
      ],
      'UX Designer': [
        { name: 'User Research', description: 'Understanding user needs through research and testing', weight: 30 },
        { name: 'Design Skills', description: 'UI/UX design principles and tools proficiency', weight: 35 },
        { name: 'Prototyping', description: 'Creating interactive prototypes and wireframes', weight: 20 },
        { name: 'Collaboration', description: 'Working with cross-functional teams and stakeholders', weight: 15 }
      ],
      'DevOps Engineer': [
        { name: 'Infrastructure', description: 'Cloud platforms, containers, and infrastructure management', weight: 35 },
        { name: 'Automation', description: 'CI/CD pipelines and infrastructure as code', weight: 30 },
        { name: 'Monitoring', description: 'System monitoring, logging, and alerting', weight: 20 },
        { name: 'Security', description: 'Security best practices and compliance', weight: 15 }
      ]
    };
    return examples[role] || [
      { name: 'Technical Skills', description: 'Core technical abilities relevant to the role', weight: 40 },
      { name: 'Problem Solving', description: 'Analytical thinking and approach to challenges', weight: 30 },
      { name: 'Communication', description: 'Verbal and written communication skills', weight: 20 },
      { name: 'Leadership', description: 'Team management and leadership capabilities', weight: 10 }
    ];
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  // Parameter management functions
  const loadParameters = useCallback(async () => {
    setIsLoadingParameters(true);
    try {
      const response = await fetch(`/api/custom-parameters/${formData.position}`);
      if (response.ok) {
        const data = await response.json();
        setCustomParameters(data.parameters || {});
        setParametersSaved(Object.keys(data.parameters || {}).length > 0);
      }
    } catch (error) {
      console.error('Error loading parameters:', error);
    } finally {
      setIsLoadingParameters(false);
    }
  }, [formData.position]);

  useEffect(() => {
    if (formData.position) {
      loadParameters();
    }
  }, [formData.position, loadParameters]);

  const loadExampleParameters = () => {
    const examples = getExampleParameters(formData.position);
    const parameterObject = {};
    
    examples.forEach((param, index) => {
      const key = `param_${index + 1}`;
      parameterObject[key] = {
        name: param.name,
        description: param.description,
        weight: param.weight,
        min_questions: 2,
        max_questions: 5,
        scoring_criteria: [
          'Excellent understanding and application',
          'Good knowledge with minor gaps',
          'Basic understanding with room for improvement',
          'Limited knowledge requiring significant development'
        ]
      };
    });
    
    setCustomParameters(parameterObject);
    setParametersSaved(false);
    toast.success('Example parameters loaded!');
  };

  const saveParameters = async () => {
    setIsSavingParameters(true);
    try {
      const response = await fetch('/api/custom-parameters', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          role_name: formData.position,
          custom_parameters: customParameters
        })
      });

      if (response.ok) {
        setParametersSaved(true);
        toast.success('Parameters saved successfully!');
      } else {
        throw new Error('Failed to save parameters');
      }
    } catch (error) {
      console.error('Error saving parameters:', error);
      toast.error('Failed to save parameters');
    } finally {
      setIsSavingParameters(false);
    }
  };

  const addParameter = () => {
    const newKey = `param_${Object.keys(customParameters).length + 1}`;
    setCustomParameters(prev => ({
      ...prev,
      [newKey]: {
        name: '',
        description: '',
        weight: 25,
        min_questions: 2,
        max_questions: 5,
        scoring_criteria: ['', '', '', '']
      }
    }));
  };

  const updateParameter = (key, field, value) => {
    setCustomParameters(prev => ({
      ...prev,
      [key]: {
        ...prev[key],
        [field]: value
      }
    }));
    setParametersSaved(false);
  };

  const deleteParameter = (key) => {
    setCustomParameters(prev => {
      const newParams = { ...prev };
      delete newParams[key];
      return newParams;
    });
    setParametersSaved(false);
  };

  const resetForm = () => {
    setFormData({
      candidateName: '',
      candidateEmail: '',
      position: '',
      duration: 30,
      technicalWeight: 60,
      softSkillsWeight: 40,
      customInstructions: '',
      interviewType: 'technical'
    });
    setCreatedInterview(null);
  };

  const sendInterviewLink = () => {
    if (createdInterview?.interview_id) {
      const interviewLink = `${window.location.origin}/interview/${createdInterview.interview_id}`;
      const subject = `Interview Link - ${formData.position} Position`;
      const body = `Hello ${formData.candidateName},\n\nYou have been invited to complete an interview for the ${formData.position} position.\n\nPlease click the link below to start your interview:\n${interviewLink}\n\nGood luck!\n\nBest regards,\nHR Team`;
      
      // Gmail compose link
      const gmailLink = `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(formData.candidateEmail)}&su=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
      window.open(gmailLink, '_blank');
    }
  };

  const copyEmailContent = () => {
    if (createdInterview?.interview_id) {
      const interviewLink = `${window.location.origin}/interview/${createdInterview.interview_id}`;
      const subject = `Interview Link - ${formData.position} Position`;
      const body = `Hello ${formData.candidateName},\n\nYou have been invited to complete an interview for the ${formData.position} position.\n\nPlease click the link below to start your interview:\n${interviewLink}\n\nGood luck!\n\nBest regards,\nHR Team`;
      
      const emailContent = `To: ${formData.candidateEmail}\nSubject: ${subject}\n\n${body}`;
      navigator.clipboard.writeText(emailContent);
      toast.success('Email content copied to clipboard!');
    }
  };

  const createInterview = async () => {
    if (!formData.candidateName || !formData.candidateEmail || !formData.position) {
      toast.error('Please fill in all required fields');
      return;
    }

    // Check if parameters are configured
    if (Object.keys(customParameters).length === 0) {
      toast.error('Please configure assessment parameters first. Use the "Parameters" tab to set up parameters for this role.');
      setShowParametersTab(true);
      return;
    }

    setIsCreating(true);
    
    try {
      const response = await fetch('/api/create-interview', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          candidate_name: formData.candidateName,
          candidate_email: formData.candidateEmail,
          position: formData.position,
          duration_minutes: parseInt(formData.duration),
          technical_weight: parseInt(formData.technicalWeight),
          soft_skills_weight: parseInt(formData.softSkillsWeight),
          custom_instructions: formData.customInstructions,
          interview_type: formData.interviewType
        })
      });

      if (response.ok) {
        const result = await response.json();
        setCreatedInterview(result);
        toast.success('Interview created successfully!');
      } else {
        toast.error('Failed to create interview');
      }
    } catch (error) {
      console.error('Error creating interview:', error);
      toast.error('Failed to create interview');
    } finally {
      setIsCreating(false);
    }
  };

  const copyInterviewLink = () => {
    if (createdInterview?.interview_id) {
      const interviewLink = `${window.location.origin}/interview/${createdInterview.interview_id}`;
      navigator.clipboard.writeText(interviewLink);
      toast.success('Interview link copied to clipboard!');
    }
  };



  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-6">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="bg-white rounded-lg shadow-lg p-6 mb-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-800 flex items-center gap-3">
                <UserPlus className="text-blue-600" />
                Create Interview
              </h1>
              <p className="text-gray-600 mt-2">
                Set up an interview and generate a link for your candidate
              </p>
            </div>
            <button
              onClick={() => navigate('/dashboard')}
              className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors"
            >
              Back to Dashboard
            </button>
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="bg-white rounded-lg shadow-lg mb-6">
          <div className="border-b border-gray-200">
            <nav className="flex space-x-8 px-6">
              <button
                onClick={() => setShowParametersTab(false)}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  !showParametersTab
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Interview Setup
              </button>
              <button
                onClick={() => setShowParametersTab(true)}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  showParametersTab
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                Assessment Parameters
                {!parametersSaved && Object.keys(customParameters).length > 0 && (
                  <span className="ml-2 inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800">
                    Unsaved
                  </span>
                )}
              </button>
            </nav>
          </div>
        </div>

        {!showParametersTab ? (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Interview Creation Form */}
            <div className="bg-white rounded-lg shadow-lg p-6">
              <h2 className="text-xl font-semibold text-gray-800 mb-4 flex items-center gap-2">
                <Settings className="text-blue-600" />
                Interview Configuration
              </h2>

            <div className="space-y-4">
              {/* Candidate Information */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Candidate Name *
                </label>
                <input
                  type="text"
                  name="candidateName"
                  value={formData.candidateName}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="Enter candidate's full name"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Candidate Email *
                </label>
                <input
                  type="email"
                  name="candidateEmail"
                  value={formData.candidateEmail}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="candidate@example.com"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Position *
                </label>
                <select
                  name="position"
                  value={formData.position}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                >
                  <option value="">Select a position</option>
                  {positions.map((pos) => (
                    <option key={pos} value={pos}>{pos}</option>
                  ))}
                </select>
              </div>

              {/* Interview Settings */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Interview Type
                </label>
                <div className="grid grid-cols-1 gap-2">
                  {interviewTypes.map((type) => (
                    <label key={type.value} className="flex items-center p-3 border border-gray-200 rounded-lg cursor-pointer hover:bg-gray-50">
                      <input
                        type="radio"
                        name="interviewType"
                        value={type.value}
                        checked={formData.interviewType === type.value}
                        onChange={handleInputChange}
                        className="mr-3"
                      />
                      <span className="text-lg mr-2">{type.icon}</span>
                      <span>{type.label}</span>
                    </label>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Duration (minutes)
                </label>
                <select
                  name="duration"
                  value={formData.duration}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                >
                  <option value={15}>15 minutes</option>
                  <option value={30}>30 minutes</option>
                  <option value={45}>45 minutes</option>
                  <option value={60}>60 minutes</option>
                </select>
              </div>

              {/* Scoring Weights */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Technical Skills Weight (%)
                </label>
                <input
                  type="range"
                  name="technicalWeight"
                  min="0"
                  max="100"
                  value={formData.technicalWeight}
                  onChange={handleInputChange}
                  className="w-full"
                />
                <div className="flex justify-between text-sm text-gray-500">
                  <span>0%</span>
                  <span>{formData.technicalWeight}%</span>
                  <span>100%</span>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Soft Skills Weight (%)
                </label>
                <input
                  type="range"
                  name="softSkillsWeight"
                  min="0"
                  max="100"
                  value={formData.softSkillsWeight}
                  onChange={handleInputChange}
                  className="w-full"
                />
                <div className="flex justify-between text-sm text-gray-500">
                  <span>0%</span>
                  <span>{formData.softSkillsWeight}%</span>
                  <span>100%</span>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Custom Instructions (Optional)
                </label>
                <textarea
                  name="customInstructions"
                  value={formData.customInstructions}
                  onChange={handleInputChange}
                  rows="3"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="Any specific instructions or focus areas for this interview..."
                />
              </div>

              <button
                onClick={createInterview}
                disabled={isCreating}
                className="w-full bg-blue-600 text-white py-3 px-4 rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center justify-center gap-2"
              >
                {isCreating ? (
                  <>
                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                    Creating Interview...
                  </>
                ) : (
                  <>
                    <UserPlus className="w-5 h-5" />
                    Create Interview
                  </>
                )}
              </button>
            </div>
          </div>

          {/* Interview Link & Actions */}
          <div className="bg-white rounded-lg shadow-lg p-6">
            <h2 className="text-xl font-semibold text-gray-800 mb-4 flex items-center gap-2">
              <Send className="text-green-600" />
              Interview Link
            </h2>

            {createdInterview ? (
              <div className="space-y-4">
                <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                  <h3 className="font-semibold text-green-800 mb-2">✅ Interview Created Successfully!</h3>
                  <div className="space-y-2 text-sm text-green-700">
                    <p><strong>Candidate:</strong> {formData.candidateName}</p>
                    <p><strong>Position:</strong> {formData.position}</p>
                    <p><strong>Duration:</strong> {formData.duration} minutes</p>
                    <p><strong>Interview ID:</strong> {createdInterview.interview_id}</p>
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Interview Link
                  </label>
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={`${window.location.origin}/interview/${createdInterview.interview_id}`}
                      readOnly
                      className="flex-1 px-3 py-2 border border-gray-300 rounded-lg bg-gray-50"
                    />
                    <button
                      onClick={copyInterviewLink}
                      className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors flex items-center gap-2"
                    >
                      <Copy className="w-4 h-4" />
                      Copy
                    </button>
                  </div>
                </div>

                                 <div className="space-y-2">
                   <button
                     onClick={sendInterviewLink}
                     className="w-full bg-green-600 text-white py-3 px-4 rounded-lg hover:bg-green-700 transition-colors flex items-center justify-center gap-2"
                   >
                     <Send className="w-4 h-4" />
                     Send via Gmail
                   </button>
                   
                   <button
                     onClick={copyEmailContent}
                     className="w-full bg-purple-600 text-white py-3 px-4 rounded-lg hover:bg-purple-700 transition-colors flex items-center justify-center gap-2"
                   >
                     <Copy className="w-4 h-4" />
                     Copy Email Content
                   </button>
                   
                   <button
                     onClick={() => window.open(`${window.location.origin}/interview/${createdInterview.interview_id}`, '_blank')}
                     className="w-full bg-blue-600 text-white py-3 px-4 rounded-lg hover:bg-blue-700 transition-colors flex items-center justify-center gap-2"
                   >
                     <FileText className="w-4 h-4" />
                     Test Interview Link
                   </button>
                 </div>

                <button
                  onClick={resetForm}
                  className="w-full bg-gray-100 text-gray-700 py-2 px-4 rounded-lg hover:bg-gray-200 transition-colors"
                >
                  Create Another Interview
                </button>
              </div>
            ) : (
              <div className="text-center py-12 text-gray-500">
                <UserPlus className="w-16 h-16 mx-auto mb-4 text-gray-300" />
                <p>Create an interview to generate a link for your candidate</p>
              </div>
            )}
          </div>
        </div>
        ) : (
          /* Parameters Tab */
          <div className="bg-white rounded-lg shadow-lg p-6">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-semibold text-gray-800 flex items-center gap-2">
                <Target className="text-blue-600" />
                Assessment Parameters for {formData.position || 'Selected Role'}
              </h2>
              <div className="flex gap-2">
                <button
                  onClick={loadExampleParameters}
                  className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors flex items-center gap-2"
                >
                  <Brain className="w-4 h-4" />
                  Load Examples
                </button>
                <button
                  onClick={saveParameters}
                  disabled={isSavingParameters || Object.keys(customParameters).length === 0}
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex items-center gap-2"
                >
                  {isSavingParameters ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      Saving...
                    </>
                  ) : (
                    <>
                      <Save className="w-4 h-4" />
                      Save Parameters
                    </>
                  )}
                </button>
              </div>
            </div>

            {isLoadingParameters ? (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
                <span className="ml-2 text-gray-600">Loading parameters...</span>
              </div>
            ) : (
              <div className="space-y-6">
                {Object.keys(customParameters).length === 0 ? (
                  <div className="text-center py-8">
                    <Target className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                    <h3 className="text-lg font-medium text-gray-900 mb-2">No Parameters Configured</h3>
                    <p className="text-gray-600 mb-4">
                      Configure assessment parameters for {formData.position || 'this role'} to create targeted interviews.
                    </p>
                    <button
                      onClick={loadExampleParameters}
                      className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2 mx-auto"
                    >
                      <Brain className="w-4 h-4" />
                      Load Example Parameters
                    </button>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {Object.entries(customParameters).map(([key, param]) => (
                      <div key={key} className="border border-gray-200 rounded-lg p-4">
                        <div className="flex items-start justify-between mb-3">
                          <div className="flex-1">
                            <input
                              type="text"
                              value={param.name}
                              onChange={(e) => updateParameter(key, 'name', e.target.value)}
                              placeholder="Parameter name"
                              className="text-lg font-semibold text-gray-900 bg-transparent border-none outline-none w-full"
                            />
                          </div>
                          <div className="flex items-center gap-2">
                            <button
                              onClick={() => deleteParameter(key)}
                              className="p-1 text-red-500 hover:text-red-700 transition-colors"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        </div>
                        
                        <textarea
                          value={param.description}
                          onChange={(e) => updateParameter(key, 'description', e.target.value)}
                          placeholder="Parameter description"
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent mb-3"
                          rows="2"
                        />
                        
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                              Weight (%)
                            </label>
                            <input
                              type="number"
                              value={param.weight}
                              onChange={(e) => updateParameter(key, 'weight', parseInt(e.target.value))}
                              min="1"
                              max="100"
                              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                              Min Questions
                            </label>
                            <input
                              type="number"
                              value={param.min_questions}
                              onChange={(e) => updateParameter(key, 'min_questions', parseInt(e.target.value))}
                              min="1"
                              max="10"
                              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                              Max Questions
                            </label>
                            <input
                              type="number"
                              value={param.max_questions}
                              onChange={(e) => updateParameter(key, 'max_questions', parseInt(e.target.value))}
                              min="1"
                              max="10"
                              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            />
                          </div>
                        </div>
                      </div>
                    ))}
                    
                    <button
                      onClick={addParameter}
                      className="w-full py-3 px-4 border-2 border-dashed border-gray-300 rounded-lg text-gray-600 hover:border-blue-500 hover:text-blue-600 transition-colors flex items-center justify-center gap-2"
                    >
                      <Plus className="w-4 h-4" />
                      Add Parameter
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default HRInterviewCreator;
